<article class="panel job-card internal-job-card"><div class="job-top"><div class="person-identity"><span class="job-logo"><?= e(mb_substr($companyName,0,2)) ?></span><div><h3><a href="/jobs/<?= e($job['id']) ?>"><?= e($job['title']) ?></a></h3><p class="job-company"><a href="/company/<?= e($job['companyId']) ?>"><?= e($companyName) ?></a> · <?= e($job['level']) ?> · <?= e($job['jobType']) ?> · <?= e($job['location']??'Remote') ?></p><p class="job-salary"><?= e(ui_salary($job)) ?></p></div></div><div class="row"><span class="status-badge status-<?= e($job['status']) ?>"><?= e($job['status']) ?></span><?php if($user): ?><button class="icon-button <?= $saved?'positive':'' ?>" data-job-save="<?= e($job['id']) ?>" data-external="false" aria-pressed="<?= $saved?'true':'false' ?>" aria-label="<?= $saved?'Bỏ lưu việc làm':'Lưu việc làm' ?>"><?= ui_icon('bookmark',18) ?></button><?php else: ?><a class="icon-button" href="/auth/sign-in" aria-label="Đăng nhập để lưu việc làm"><?= ui_icon('bookmark',18) ?></a><?php endif; ?></div></div><div class="chips"><?php foreach(array_slice($jobSkills,0,5) as $skill): ?><span class="skill-match"><?= e($skill) ?></span><?php endforeach; if(count($jobSkills)>5): ?><span>+<?= count($jobSkills)-5 ?></span><?php endif; ?></div><div class="job-actions"><small class="muted"><?= (int)($job['_count']['applications']??0) ?> ứng viên · Hết hạn <?= !empty($job['expiresAt'])?e(date('d/m/Y',strtotime($job['expiresAt']))):'—' ?></small><a class="button" href="/jobs/<?= e($job['id']) ?>">Xem & ứng tuyển</a></div></article>